// EmailJS Configuration
// Replace these placeholder values with your actual EmailJS credentials

export const EMAILJS_CONFIG = {
  // Your EmailJS Public Key
  PUBLIC_KEY: 'YOUR_PUBLIC_KEY_HERE',
  
  // Your EmailJS Service ID
  SERVICE_ID: 'YOUR_SERVICE_ID_HERE',
  
  // Your EmailJS Template ID
  TEMPLATE_ID: 'YOUR_TEMPLATE_ID_HERE',
  
  // Recipient email (your email)
  RECIPIENT_EMAIL: 'gabepineda6@gmail.com'
};

// How to get these values:
// 1. Go to https://www.emailjs.com/ and create an account
// 2. Create a new Email Service (Gmail, Outlook, etc.)
// 3. Create a new Email Template
// 4. Get your Public Key from Account > API Keys
// 5. Get your Service ID from Email Services
// 6. Get your Template ID from Email Templates
